<?php
$categories = $pdo->query('SELECT c.id, c.name, c.created_at, COUNT(t.id) AS task_count FROM categories c LEFT JOIN tasks t ON t.category_id = c.id GROUP BY c.id ORDER BY c.name')->fetchAll();
?>
